import type { Corpus } from './corpus.js';
import type { RegistryEntry } from './corpus-index.js';
import { listRefs } from './ref.js';

export interface RegistryTypesOptions {
  /** Module augmented by the declaration (default `'tsprose'`). */
  readonly module?: string | undefined;
  /** Interface name (default `'CorpusRegistry'`). */
  readonly interfaceName?: string | undefined;
  /** First line comment (default: a "generated, do not edit" notice). */
  readonly header?: string | undefined;
}

/**
 * Declaration text that augments {@link CorpusRegistry} with documents, their element names and tag names, so
 * `ref('dem/1234', 'solution')` is checked and completed by the editor. Entries can come from anywhere:
 * `index.registryEntries()` after a build, {@link registryEntriesFromCorpus} without compiling, a database, a manifest.
 * Write the result to a `.d.ts` file included by the project's tsconfig.
 */
export function generateRegistryTypes(entries: Iterable<RegistryEntry>, options: RegistryTypesOptions = {}): string {
  const module = options.module ?? 'tsprose';
  const name = options.interfaceName ?? 'CorpusRegistry';
  const lines = [
    `// ${options.header ?? 'Generated by tsprose (generateRegistryTypes). Do not edit.'}`,
    'export {};',
    '',
    `declare module ${JSON.stringify(module)} {`,
    `  interface ${name} {`,
  ];
  const sorted = [...entries].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  for (const entry of sorted) {
    const names = Object.entries(entry.names).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    if (!names.length) {
      lines.push(`    ${JSON.stringify(entry.id)}: {};`);
      continue;
    }
    lines.push(`    ${JSON.stringify(entry.id)}: { ${names.map(([n, t]) => `${JSON.stringify(n)}: ${JSON.stringify(t)};`).join(' ')} };`);
  }
  lines.push('  }', '}', '');
  return lines.join('\n');
}

/**
 * Registry entries from the declared refs (`defineRefs`) of a corpus — without compiling anything, so a watcher can
 * regenerate types on every save. String refs (`$="name"`) are only known after compilation; use
 * `index.registryEntries()` for them.
 */
export function registryEntriesFromCorpus(corpus: Corpus): RegistryEntry[] {
  return corpus.entries().map(([id, doc]) => ({
    id,
    names: Object.fromEntries(doc.refs.flatMap((r) => listRefs(r)).map((handle) => [handle.name, handle.def.name])),
  }));
}
